import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement with no invoices', () => {
  const result = statement('C-001', [], '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement with single issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2023-0001');
  assert.equal(result.value.invoices[0].issueDate, '2023-10-15');
  assert.ok(result.value.invoices[0].total > 0);
  assert.equal(result.value.totalDue, result.value.invoices[0].due);
});

test('statement filters invoices by issueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-11-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);
  const invoices = [issued1.value, issued2.value];

  const result = statement('C-001', invoices, '2023-11-01');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-15');
});

test('statement includes invoices up to and including asOf date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-31',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);
  const invoices = [issued1.value, issued2.value];

  const result = statement('C-001', invoices, '2023-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
});

test('statement excludes invoices after asOf date', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-11-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);
  const invoices = [issued1.value, issued2.value];

  const result = statement('C-001', invoices, '2023-11-01');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-15');
});

test('statement ignores draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const invoices = [r.value]; // still in draft status

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement ignores paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = require('../src/invoices.js').invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2023-10-20' });
  const invoices = [paid.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const partial = recordPayment(issued.value, { amount: 10000, date: '2023-10-20' });
  const invoices = [partial.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.ok(result.value.invoices[0].due > 0);
});

test('statement filters by customer ID', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2023-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);
  const invoices = [issued1.value, issued2.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2023-0001');
});

test('statement ignores invoices from other customers', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2023-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);
  const invoices = [issued1.value, issued2.value];

  const result = statement('C-003', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-20');
});

test('statement sorts invoices by issueDate', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);

  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued3 = issueInvoice(r3.value, ['INV-2023-0002']);

  const invoices = [issued1.value, issued2.value, issued3.value];
  const result = statement('C-001', invoices, '2023-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-10');
  assert.equal(result.value.invoices[1].issueDate, '2023-10-15');
  assert.equal(result.value.invoices[2].issueDate, '2023-10-20');
});

test('statement calculates totalDue as sum of due amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);

  const invoices = [issued1.value, issued2.value];
  const result = statement('C-001', invoices, '2023-12-31');

  assert.equal(result.ok, true);
  const due1 = result.value.invoices[0].due;
  const due2 = result.value.invoices[1].due;
  assert.equal(result.value.totalDue, due1 + due2);
});

test('statement error: CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = statement('C-999', [], '2023-12-31');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('statement normalizes customer ID', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];

  const result = statement('c-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('statement normalizes customer ID with whitespace', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];

  const result = statement(' c-001 ', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('statement includes invoices with vouchers', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const vouched = applyVoucher(issued.value, { code: 'SAVE10', amount: 1000 });
  const invoices = [vouched.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.ok(result.value.invoices[0].total > 0);
});

test('statement includes invoices with payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const paid = recordPayment(issued.value, { amount: 5000, date: '2023-10-20' });
  const invoices = [paid.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.ok(result.value.invoices[0].due < result.value.invoices[0].total);
});

test('statement includes issueDate and dueDate', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-15');
  assert.equal(result.value.invoices[0].dueDate, '2023-10-29');
});

test('statement includes invoice number', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];

  const result = statement('C-001', invoices, '2023-12-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].number, 'INV-2023-0001');
});

test('statement with multiple customers and invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);

  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2023-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued3 = issueInvoice(r3.value, ['INV-2023-0002']);

  const invoices = [issued1.value, issued2.value, issued3.value];
  const result = statement('C-001', invoices, '2023-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-15');
  assert.equal(result.value.invoices[1].issueDate, '2023-10-20');
});

test('statement with all issued and partially_paid invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, []);

  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2023-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2023-0001']);
  const partial = recordPayment(issued2.value, { amount: 10000, date: '2023-10-25' });

  const invoices = [issued1.value, partial.value];
  const result = statement('C-001', invoices, '2023-12-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2023-10-15');
  assert.equal(result.value.invoices[1].issueDate, '2023-10-20');
});

